baseline_text.src/culturemech/schema/culturemech.schem:
{
    "$defs": {
        "AtmosphereEnum": {
            "description": "Atmospheric conditions for incubation",
            "enum": [
                "AEROBIC",
                "ANAEROBIC",
                "MICROAEROPHILIC"
            ],
            "title": "AtmosphereEnum",
            "type": "string"
        },
        "CategoryEnum": {
            "description": "Organizational category for media recipes",
            "enum": [
                "bacterial",
                "fungal",
                "archaea",
                "specialized",
                "algae",
                "imported"
            ],
            "title": "CategoryEnum",
            "type": "string"
        },
        "CellularMetabolicRoleEnum": {
            "description": "Role of the ingredient inside or on the cultured microbe(s) \u2014 the compound's metabolic fate or biochemical function at the cell level. One of three orthogonal role facets (with NutritionalRoleEnum and PhysicochemicalRoleEnum). Values in this facet are often organism-conditional (e.g. ELECTRON_DONOR applies only for organisms that oxidize the compound for energy; methanol is an electron donor for methylotrophs but only a carbon source for others).",
            "enum": [
                "SUBSTRATE",
                "ELECTRON_DONOR",
                "ELECTRON_ACCEPTOR",
                "COFACTOR",
                "PROSTHETIC_GROUP_PRECURSOR",
                "MEMBRANE_COMPONENT",
                "OSMOPROTECTANT",
                "INDUCER",
                "INHIBITOR",
                "QUENCHER"
            ],
            "title": "CellularMetabolicRoleEnum",
            "type": "string"
        },
        "ChebiTerm": {
            "additionalProperties": false,
            "description": "A strictly-CHEBI term reference. Use for the `chebi_term` slot where the contract is \"this is the CHEBI grounding specifically\" \u2014 distinct from the polymorphic `ChemicalEntityTerm` used by `term` slots that may carry upstream non-CHEBI IDs.",
            "properties": {
                "confidence": {
                    "description": "Confidence score for the mapping (0.0-1.0). Populated by automated grounding pipelines.",
                    "type": [
                        "number",
                        "null"
                    ]
                },
                "id": {
                    "description": "Ontology identifier (CURIE)",
                    "pattern": "^CHEBI:\\d+$",
                    "type": "string"
                },
                "label": {
                    "description": "CANONICAL ontology label for `id` (e.g. \"magnesium sulfate\" for CHEBI:32599). Verified against the ontology by the id\u2194label gate; the sibling `preferred_term` holds the free/source name.",
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "match_type": {
                    "$ref": "#/$defs/TermMatchTypeEnum",
                    "description": "Provenance/method of the term mapping (e.g. \"kg_fallback\", \"exact\", \"manual_curated\")."
                }
            },
            "required": [
                "id"
            ],
            "title": "ChebiTerm",
            "type": "object"
        },
        "ChemicalEntityTerm": {
            "additionalProperties": false,
            "description": "A term identifying a chemical or biological ingredient. Primarily CHEBI, with FOODON / UBERON / ENVO accepted for ingredients (food products, anatomical tissues, environmental samples) where no CHEBI equivalent exists upstream. `mediadive.compound:*` is also accepted as the upstream MediaDive grounding kept alongside CHEBI mappings on solution-composition entries. MICRO (Ontology of Prokaryotic Phenotypic and Metabolic Characters) is accepted for enzymatic protein digests (tryptone, peptone, proteose peptone, soy peptone, casein hydrolysate) which ChEBI cannot represent because CHEBI:59999 \"chemical substance\" requires constant composition.",
            "properties": {
                "confidence": {
                    "description": "Confidence score for the mapping (0.0-1.0). Populated by automated grounding pipelines.",
                    "type": [
                        "number",
                        "null"
                    ]
                },
                "id": {
                    "description": "Ontology identifier (CURIE)",
                    "pattern": "^(CHEBI|FOODON|MICRO|UBERON|ENVO|mediadive\\.compound):\\w+$",
                    "type": "string"
                },
                "label": {
                    "description": "CANONICAL ontology label for `id` (e.g. \"magnesium sulfate\" for CHEBI:32599). Verified against the ontology by the id\u2194label gate; the sibling `preferred_term` holds the free/source name.",
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "match_type": {
                    "$ref": "#/$defs/TermMatchTypeEnum",
                    "description": "Provenance/method of the term mapping (e.g. \"kg_fallback\", \"exact\", \"manual_curated\")."
                }
            },
            "required": [
                "id"
            ],
            "title": "ChemicalEntityTerm",
            "type": "object"
        },
        "CofactorCategoryEnum": {
            "description": "High-level classification of cofactor types",
            "enum": [
                "VITAMINS",
                "METALS",
                "NUCLEOTIDES",
                "ENERGY_TRANSFER",
                "OTHER_SPECIALIZED"
            ],
            "title": "CofactorCategoryEnum",
            "type": "string"
        },
        "CofactorDescriptor": {
            "additionalProperties": false,
            "description": "A cofactor or coenzyme required for enzymatic activity",
            "properties": {
                "bioavailability": {
                    "description": "Uptake and availability characteristics",
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "biosynthesis_genes": {
                    "description": "Genes involved in cofactor biosynthesis",
                    "items": {
                        "type": "string"
                    },
                    "type": [
                        "array",
                        "null"
                    ]
                },
                "category": {
                    "$ref": "#/$defs/CofactorCategoryEnum",
                    "description": "High-level classification"
                },
                "ec_associations": {
                    "description": "EC numbers of enzymes using this cofactor",
                    "items": {
                        "type": "string"
                    },
                    "type": [
                        "array",
                        "null"
                    ]
                },
                "enzyme_examples": {
                    "description": "Example enzymes requiring this cofactor",
                    "items": {
                        "type": "string"
                    },
                    "type": [
                        "array",
                        "null"
                    ]
                },
                "kegg_pathways": {
                    "description": "KEGG pathway IDs for biosynthesis",
                    "items": {
                        "type": "string"
                    },
                    "type": [
                        "array",
                        "null"
                    ]
                },
                "notes": {
                    "description": "Additional information about the cofactor",
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "precursor": {
                    "description": "Precursor molecule (e.g., thiamine \u2192 TPP)",
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "precursor_term": {
                    "anyOf": [
                        {
                            "$ref": "#/$defs/ChemicalEntityTerm"
                        },
                        {
                            "type": "null"
                        }
                    ],
                    "description": "CHEBI term for precursor"
                },
                "preferred_term": {
                    "description": "Human-readable cofactor name (e.g., \"Thiamine pyrophosphate\", \"NAD\")",
                    "type": "string"
                },
                "term": {
                    "anyOf": [
                        {
                            "$ref": "#/$defs/ChemicalEntityTerm"
                        },
                        {
                            "type": "null"
                        }
                    ],
                    "description": "CHEBI term for the cofactor"
                }
            },
            "required": [
                "preferred_term"
            ],
            "title": "CofactorDescriptor",
            "type": "object"
        },
        "CofactorRequirement": {
            "additionalProperties": false,
            "description": "Cofactor requirement for an organism",
            "properties": {
                "can_biosynthesize": {
                    "description": "Whether organism can synthesize this cofactor",
                    "type": "boolean"
                },
                "cofactor": {
                    "$ref": "#/$defs/CofactorDescriptor",
                    "description": "Required cofactor"
                },
                "confidence": {
                    "description": "Confidence level (0.0-1.0) based on genome annotation",
                    "type": [
                        "number",
                        "null"
                    ]
                },
                "evidence": {
                    "description": "Supporting evidence for requirement",
                    "items": {
                        "$ref": "#/$defs/EvidenceItem"
                    },
                    "type": [
                        "array",
                        "null"
                    ]
                },
                "genes": {
                    "description": "Genes related to biosynthesis or utilization",
                    "items": {
                        "type": "string"
                    },
                    "type": [
                        "array",
                        "null"
                    ]
                }
            },
            "required": [
                "cofactor",
                "can_biosynthesize"
            ],
            "title": "CofactorRequirement",
            "type": "object"
        },
        "CommunityOrganismRoleEnum": {
            "description": "Role an organism plays in a microbial community (formerly `CellularRoleEnum`; renamed 2026-07-19 for consistency with the MIM #120 rename and to disambiguate from a forthcoming `CellularMetabolicRoleEnum` on ingredient records \u2014 these values describe organisms, not ingredients).",
            "enum": [
                "PRIMARY_DEGRADER",
                "REDUCTIVE_DEGRADER",
                "OXIDATIVE_DEGRADER",
                "BIOTRANSFORMER",
                "SYNERGIST",
                "BRIDGE_ORGANISM",
                "ELECTRON_SHUTTLE",
                "DETOXIFIER",
                "COMMENSAL",
                "COMPETITOR"
            ],
            "title": "CommunityOrganismRoleEnum",
            "type": "string"
        },
        "ConcentrationBasisEnum": {
            "description": "How a proposed concentration was arrived at. Ordered from strongest to weakest, because the distinction is the whole point of recording a candidate rather than an asserted value.",
            "enum": [
                "READ_FROM_THIS_MEDIUM",
                "READ_FROM_STOCK_DEFINITION",
                "CROSS_MEDIUM_INFERENCE",
                "TYPICAL_VALUE"
            ],
            "title": "ConcentrationBasisEnum",
            "type": "string"
        },
        "ConcentrationCandidate": {
            "additionalProperties": false,
            "description": "A concentration that has been PROPOSED but not asserted, carrying the basis it rests on and the evidence for it.\nThis exists so an inferred value can be recorded without being mistaken for one that was read from a source. A candidate never overwrites an asserted `concentration`; promoting it is a curation decision, made after checking the record's own source.",
            "properties": {
                "basis": {
                    "$ref": "#/$defs/ConcentrationBasisEnum",
                    "description": "What kind of claim this is \u2014 how the value was arrived at."
                },
                "counterevidence": {
                    "description": "Evidence AGAINST this candidate, where any is known. Recorded because a candidate offered without its known counterexample invites the reader to trust it more than the evidence allows.",
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "proposed_by": {
                    "description": "Script or curator that proposed the value.",
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "proposed_on": {
                    "description": "ISO-8601 date the proposal was made.",
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "source": {
                    "description": "Citation or URL the support was read from.",
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "support": {
                    "description": "The evidence, stated so it can be re-checked, e.g. \"10 of 11 MediaDive media citing this stock add it at this volume\".",
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "unit": {
                    "$ref": "#/$defs/ConcentrationUnitEnum",
                    "description": "Concentration unit"
                },
                "value": {
                    "description": "Numeric value or range, as the evidence gives it.",
                    "type": "string"
                }
            },
            "required": [
                "value",
                "unit",
                "basis"
            ],
            "title": "ConcentrationCandidate",
            "type": "object"
        },
        "ConcentrationUnitEnum": {
            "description": "Units for concentration",
            "enum": [
                "G_PER_L",
                "MG_PER_L",
                "MICROG_PER_L",
                "MOLAR",
                "MILLIMOLAR",
                "MICROMOLAR",
                "PERCENT_W_V",
                "PERCENT_W_W",
                "PERCENT_V_V",
                "ML_PER_L",
                "MG_PER_ML",
                "FOLD_DILUTION",
                "L",
                "VARIABLE"
            ],
            "title": "ConcentrationUnitEnum",
            "type": "string"
        },
        "ConcentrationValue": {
            "additionalProperties": false,
            "description": "Quantified concentration with units",
            "properties": {
                "per_volume": {
                    "description": "Volume basis (e.g., \"per liter\", \"per 100 mL\")",
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "unit": {
                    "$ref": "#/$defs/ConcentrationUnitEnum",
                    "description": "Concentration unit"
                },
                "value": {
                    "description": "Numeric value or range",
                    "type": "string"
                }
            },
            "required": [
                "value",
                "unit"
            ],
            "title": "ConcentrationValue",
            "type": "object"
        },
        "CultureMechTerm": {
            "additionalProperties": false,
            "description": "A CultureMech identifier for a media recipe used as component",
            "properties": {
                "confidence": {
                    "description": "Confidence score for the mapping (0.0-1.0). Populated by automated grounding pipelines.",
                    "type": [
                        "number",
                        "null"
                    ]
                },
                "id": {
                    "description": "CultureMech identifier (e.g., \"CultureMech:009592\")",
                    "pattern": "^CultureMech:\\d{6}$",
                    "type": "string"
                },
                "label": {
                    "description": "CANONICAL ontology label for `id` (e.g. \"magnesium sulfate\" for CHEBI:32599). Verified against the ontology by the id\u2194label gate; the sibling `preferred_term` holds the free/source name.",
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "match_type": {
                    "$ref": "#/$defs/TermMatchTypeEnum",
                    "description": "Provenance/method of the term mapping (e.g. \"kg_fallback\", \"exact\", \"manual_curated\")."
                }
            },
            "required": [
                "id"
            ],
            "title": "CultureMechTerm",
            "type": "object"
        },
        "CurationEvent": {
            "additionalProperties": false,
            "description": "Audit trail entry for curation",
            "properties": {
                "action": {
                    "description": "Action taken (created, updated, validated, etc.)",
                    "type": "string"
                },
                "changes": {
                    "description": "Structured summary of what changed in this event (free-text or semi-structured; used by automated curators e.g. `Set category to 'bacterial' (was: MISSING)`).",
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "curator": {
                    "description": "Name or identifier of curator",
                    "type": "string"
                },
                "notes": {
                    "description": "Additional context",
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "source": {
                    "description": "Source attribution for this curation event (e.g. a source PDF, a sibling CultureMech recipe, an external dataset).",
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "timestamp": {
                    "description": "ISO 8601 timestamp with a plausible 21st-century curation year",
                    "pattern": "^20[0-9]{2}-",
                    "type": "string"
                }
            },
            "required": [
                "timestamp",
                "curator",
                "action"
            ],
            "title": "CurationEvent",
            "type": "object"
        },
        "Dataset": {
            "additionalProperties": false,
            "description": "A reference to a publicly available dataset (omics, sequence, phenotype) relevant to this record. A lightweight repository-accession reference, not a full Datasheets-for-Datasets / DCAT description.",
            "properties": {
                "accession": {
                    "description": "Repository accession or CURIE, e.g. `geo:GSE36701`, `NCBI_SRA:SRP...`. (CultureMech `dataset_id` migrates here.)",
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "conditions": {
                    "description": "Experimental conditions / groups represented.",
                    "items": {
                        "type": "string"
                    },
                    "type": [
                        "array",
                        "null"
                    ]
                },
                "dataset_type": {
                    "$ref": "#/$defs/DatasetTypeEnum"
                },
                "description": {
                    "description": "Human-readable description; may add nuance beyond the title.",
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "evidence": {
                    "description": "Supporting citations.",
                    "items": {
                        "$ref": "#/$defs/SupportingReference"
                    },
                    "type": [
                        "array",
                        "null"
                    ]
                },
                "findings": {
                    "description": "Brief note on what the dataset shows relevant to this record.",
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "notes": {
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "organism": {
                    "description": "Source organism / community label (free text or CURIE).",
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "platform": {
                    "description": "Sequencing/assay platform.",
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "publication": {
                    "description": "Associated publication reference (e.g. PMID:...).",
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "repository": {
                    "$ref": "#/$defs/DatasetRepositoryEnum"
                },
                "sample_count": {
                    "type": [
                        "integer",
                        "null"
                    ]
                },
                "sample_types": {
                    "description": "Sample/material types represented (free text or term labels).",
                    "items": {
                        "type": "string"
                    },
                    "type": [
                        "array",
                        "null"
                    ]
                },
                "title": {
                    "description": "Short dataset title. (CommunityMech `name` migrates here.)",
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "url": {
                    "description": "Direct URL to the dataset landing page, if no CURIE applies.",
                    "format": "uri",
                    "type": [
                        "string",
                        "null"
                    ]
                }
            },
            "title": "Dataset",
            "type": "object"
        },
        "DatasetRepositoryEnum": {
            "description": "Public repository hosting the dataset. Superset of CommunityMech's enum (all values preserved) plus common additions; CultureMech datasets have no repository field today and migrate with repository unset / OTHER.",
            "enum": [
                "NCBI_SRA",
                "NCBI_BIOPROJECT",
                "NCBI_GEO",
                "NCBI_ASSEMBLY",
                "ENA",
                "ARRAYEXPRESS",
                "MGNIFY",
                "JGI_GOLD",
                "JGI_IMG",
                "NMDC",
                "METABOLOMICS_WORKBENCH",
                "METABOLIGHTS",
                "MASSIVE",
                "GNPS",
                "PRIDE",
                "DBGAP",
                "GTEX",
                "FIGSHARE",
                "ZENODO",
                "BIOMODELS",
                "KBASE",
                "OTHER"
            ],
            "title": "DatasetRepositoryEnum",
            "type": "string"
        },
        "DatasetTypeEnum": {
            "description": "Type of dataset or data resource. Canonical UNION of CultureMech's and CommunityMech's enums plus microbial additions. Migration map (old \u2192 this): CultureMech values carry over unchanged; CommunityMech GENOME\u2192GENOMICS, METAGENOME\u2192METAGENOMICS, METATRANSCRIPTOME\u2192METATRANSCRIPTOMICS, METAPROTEOME\u2192METAPROTEOMICS (AMPLICON_16S / AMPLICON_ITS / METABOLOMICS / PHENOTYPE / MULTI_OMICS / OTHER are unchanged).",
            "enum": [
                "GENOMICS",
                "METAGENOMICS",
                "AMPLICON_16S",
                "AMPLICON_ITS",
                "AMPLICON_OTHER",
                "TRANSCRIPTOMICS",
                "METATRANSCRIPTOMICS",
                "PROTEOMICS",
                "METAPROTEOMICS",
                "METABOLOMICS",
                "FLUXOMICS",
                "PHENOMICS",
                "PHENOTYPE",
                "MULTI_OMICS",
                "OTHER"
            ],
            "title": "DatasetTypeEnum",
            "type": "string"
        },
        "Descriptor": {
            "additionalProperties": false,
            "description": "Base class for descriptor pattern. Descriptors have a human-readable preferred_term and optional ontology term.",
            "title": "Descriptor",
            "type": "object"
        },
        "Discussion": {
            "additionalProperties": false,
            "description": "A thread-like record of an open question, controversy, curation todo, emerging hypothesis, knowledge gap, or interpretation debate attached to a record or one of its sub-objects. Captures the discourse / knowledge-gap layer of curation. External thread links (GitHub issues, forum posts) are cited via the `evidence` block, not a separate slot.",
            "properties": {
                "attaches_to": {
                    "description": "Hash-anchor pointers into the sections/nodes this discussion concerns: `<section>#<anchor>`, e.g. `causal_graphs#edge_x`, `composition#ingredient_y`, `ecological_interactions#z`, `ontology_mapping#m`. Free-form so each Mech can anchor into its own record structure.",
                    "items": {
                        "type": "string"
                    },
                    "type": [
                        "array",
                        "null"
                    ]
                },
                "discussion_id": {
                    "description": "Stable local identifier for this discussion thread.",
                    "type": "string"
                },
                "evidence": {
                    "description": "Supporting / contextual citations.",
                    "items": {
                        "$ref": "#/$defs/SupportingReference"
                    },
                    "type": [
                        "array",
                        "null"
                    ]
                },
                "kind": {
                    "$ref": "#/$defs/DiscussionKindEnum"
                },
                "notes": {
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "posed_by": {
                    "description": "Curator or agent that raised the discussion.",
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "posed_date": {
                    "format": "date",
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "prompt": {
                    "description": "The open question, gap statement, or todo, in one or two sentences.",
                    "type": "string"
                },
                "proposed_experiments": {
                    "description": "Optional sketches of how the gap could be resolved.",
                    "items": {
                        "$ref": "#/$defs/ProposedExperiment"
                    },
                    "type": [
                        "array",
                        "null"
                    ]
                },
                "rationale": {
                    "description": "Why this matters / what resolving it would change.",
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "resolution_note": {
                    "description": "How it was resolved (when status is RESOLVED).",
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "resolved_date": {
                    "format": "date",
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "status": {
                    "$ref": "#/$defs/DiscussionStatusEnum"
                }
            },
            "required": [
                "discussion_id",
                "prompt"
            ],
            "title": "Discussion",
            "type": "object"
        },
        "DiscussionKindEnum": {
            "description": "Kind of unresolved / in-progress item captured by a Discussion. Knowledge gaps are represented as a discussion kind so they reuse the shared pointer, evidence, and lifecycle machinery, while optional proposed experiments capture how a gap could be resolved.",
            "enum": [
                "OPEN_QUESTION",
                "KNOWLEDGE_GAP",
                "CONTROVERSY",
                "CURATION_TODO",
                "EMERGING_HYPOTHESIS",
                "INTERPRETATION",
                "HUMAN_MODEL_MISMATCH"
            ],
            "title": "DiscussionKindEnum",
            "type": "string"
        },
        "DiscussionStatusEnum": {
            "description": "Lifecycle status for a Discussion.",
            "enum": [
                "OPEN",
                "UNDER_DISCUSSION",
                "RESOLVED",
                "ARCHIVED"
            ],
            "title": "DiscussionStatusEnum",
            "type": "string"
        },
        "EnvironmentTerm": {
            "additionalProperties": false,
            "description": "An ENVO term representing an environmental system or biome",
            "properties": {
                "confidence": {
                    "description": "Confidence score for the mapping (0.0-1.0). Populated by automated grounding pipelines.",
                    "type": [
                        "number",
                        "null"
                    ]
                },
                "id": {
                    "description": "ENVO identifier (7-8 digit format)",
                    "pattern": "^ENVO:\\d{7,8}$",
                    "type": "string"
                },
                "label": {
                    "description": "CANONICAL ontology label for `id` (e.g. \"magnesium sulfate\" for CHEBI:32599). Verified against the ontology by the id\u2194label gate; the sibling `preferred_term` holds the free/source name.",
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "match_type": {
                    "$ref": "#/$defs/TermMatchTypeEnum",
                    "description": "Provenance/method of the term mapping (e.g. \"kg_fallback\", \"exact\", \"manual_curated\")."
                }
            },
            "required": [
                "id"
            ],
            "title": "EnvironmentTerm",
            "type": "object"
        },
        "EvidenceItem": {
            "additionalProperties": false,
            "description": "Evidence supporting a claim about media formulation or performance",
            "properties": {
                "explanation": {
                    "description": "Why this evidence supports the claim",
                    "type": "string"
                },
                "reference": {
                    "description": "Citation (PMID, DOI, or historical reference)",
                    "type": "string"
                },
                "snippet": {
